#include <string>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int maxNumberOfBalloons(string text) {
        unordered_map<char, int> count;
        for (char c : text) count[c]++;

        count['b'] = min(count['b'], min(count['a'], min(count['l'] / 2, min(count['o'] / 2, count['n']))));

        return count['b'];
    }
};
